fn main() {
    let mut v = vec![1, 2, 3];
    let r1 = &v;            // shared borrow
    let r2 = &v;            // another shared borrow — OK
    println!("{r1} {r2}");
    let r3 = &mut v;        // mutable borrow — OK because r1, r2 not used after
    r3.push(4);
    println!("{r3:?}");
}

fn greet(name: &str) -> String {       // takes any &str (literals, &String, etc.)
