}

#[derive(Debug, Clone)]
struct Rectangle { width: f64, height: f64 }

impl Rectangle {
    fn new(width: f64, height: f64) -> Self {
        Rectangle { width, height }
    }
    fn area(&self) -> f64 { self.width * self.height }
    fn scale(&mut self, factor: f64) {
        self.width *= factor;
        self.height *= factor;
    }
}

fn main() {
    let mut r = Rectangle::new(10.0, 5.0);
    println!("{:?}", r);
    println!("area = {}", r.area());
    r.scale(2.0);
    println!("area = {}", r.area());
}

#[derive(Debug)]
enum Shape {
    Circle(f64),
    Rectangle(f64, f64),
    Square(f64),
}

impl Shape {
    fn area(&self) -> f64 {
        match self {
            Shape::Circle(r) => std::f64::consts::PI * r * r,
            Shape::Rectangle(w, h) => w * h,
            Shape::Square(s) => s * s,
        }
    }
}

fn main() {
    let s = Shape::Rectangle(3.0, 4.0);
    println!("{:?} area = {}", s, s.area());
}

