use std::fs;
use std::io;
use std::num::ParseIntError;

fn read_count(path: &str) -> Result<i32, ParseIntError> {
    let s: String = fs::read_to_string(path)
        .map_err(|e| ParseIntError::from(e))?;  // explicit conversion
    let n: i32 = s.trim().parse()?;
    Ok(n)
}

fn largest<T: PartialOrd>(list: &[T]) -> Option<&T> {
    let mut max = &list[0];
    for item in &list[1..] {
        if item > max { max = item; }
    }
    Some(max)
}

fn main() {
    println!("{:?}", largest(&[1, 5, 3]));      // Some(5)
    println!("{:?}", largest(&['a', 'z', 'm'])); // Some('z')
}

fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() > y.len() { x } else { y }
}

fn main() {
    let s1 = String::from("long string");
    let s2 = String::from("hi");
    let r = longest(s1.as_str(), s2.as_str());
    println!("longest: {r}");
}

fn main() {
    let s = String::from("hi");
    let print = || println!("{s}");         // Fn: borrows s
    let mut s2 = String::from("hi");
    let push = || s2.push_str("!");          // FnMut: mutably borrows s2
    let consume = move || { drop(s2); };     // FnOnce + move: takes s2
    print();
    push();
    consume();
}

